import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"RELEASE-NOTES.md","filePath":"RELEASE-NOTES.md","lastUpdated":1789092097000}`),u={name:`RELEASE-NOTES.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[3]||=c(`h1`,{id:`release-notes`,tabindex:`-1`},[i(`Release notes `),c(`a`,{class:`header-anchor`,href:`#release-notes`,"aria-label":`Permalink to “Release notes”`},`​`)],-1),l[4]||=c(`h2`,{id:`_0-1-1-kid`,tabindex:`-1`},[i(`0.1.1 (Kid) `),c(`a`,{class:`header-anchor`,href:`#_0-1-1-kid`,"aria-label":`Permalink to “0.1.1 (Kid)”`},`​`)],-1),c(`p`,null,[l[1]||=i(`A maintenance update to `,-1),r(m,{term:`kid`},{default:n(()=>[...l[0]||=[i(`Kid`,-1)]]),_:1}),l[2]||=i(`, focused on everyday navigation, managing an installation and a clearer Finder installer. This release does not complete M7 or change the release line to Yearling.`,-1)]),l[5]||=a(`<h3 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to “Changes”">​</a></h3><ul><li>Sidebar labels remain visible at maximum width. The preferred starting width is 300 points and the maximum is 600 points.</li><li>Chat rendering avoids repeated layout work during updates.</li><li>Settings → General → Manage presents storage locations in an expandable tree.</li><li>Reset preferences applies the listed appearance and general defaults immediately, without restarting GOAT or clearing chats, connections, memory or permissions.</li><li>Automatic uninstall offers Partial and All presets, explicit removal choices, cancellation and a private recovery folder. It waits for GOAT to close normally. External workspaces and independently managed services are preserved.</li><li>A Retina Finder installer shows the real build number, a standard Applications-folder symbol, a separate CLI tile, aligned labels and a document-style Licence icon. Hidden support folders occupy the bottom row when shown.</li></ul><h3 id="installation-and-upgrade" tabindex="-1">Installation and upgrade <a class="header-anchor" href="#installation-and-upgrade" aria-label="Permalink to “Installation and upgrade”">​</a></h3><p>Requires Apple Silicon and macOS 26 or later. Download the signed, notarized <a href="https://github.com/goatsoft/GOAT/releases/tag/v0.1.1" target="_blank" rel="noreferrer">0.1.1 (Kid) release</a>, build 1353, with its manifest and checksums.</p><p>An ordinary upgrade replaces the app without a data reset. Finish active work before quitting to install an update, and keep a <a href="/reference/STORAGE#back-up-safely">backup of local data</a>. See <a href="/Getting-Started">Getting started</a> and <a href="/how-to/MANAGE-GOAT-DATA">Manage storage, reset preferences and uninstall</a>.</p><h3 id="qualification-and-limitations" tabindex="-1">Qualification and limitations <a class="header-anchor" href="#qualification-and-limitations" aria-label="Permalink to “Qualification and limitations”">​</a></h3><p>The maintainer accepted the tested maintenance candidate. The official package was rebuilt from the same source content and passed Developer ID signing, notarization/stapling, mounted-DMG checks, checksums and Gatekeeper assessment. Automated tests and maintainer acceptance do not establish compatibility with every engine, integration or workload.</p><p>The macOS fullscreen compositing limitation, model-template compatibility, non-interactive command boundaries and broader service/accessibility/performance qualification remain documented in <a href="/KNOWN-ISSUES">Known issues</a>. The <a href="/ROADMAP#m7-the-polish-pass">roadmap</a> tracks the remaining M7 work.</p><h2 id="_0-1-0-kid" tabindex="-1">0.1.0 (Kid) <a class="header-anchor" href="#_0-1-0-kid" aria-label="Permalink to “0.1.0 (Kid)”">​</a></h2><p>The first signed, notarized Mac download. See its immutable <a href="https://github.com/goatsoft/GOAT/releases/tag/v0.1.0" target="_blank" rel="noreferrer">release notes and artifacts</a>.</p>`,10)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};